import csv, io, json, os, sys
from datetime import datetime, timezone, timedelta
from fractions import Fraction


def read_exports(d):
    rows = []
    ex = os.path.join(d, "exports")
    for name in sorted(os.listdir(ex)):
        p = os.path.join(ex, name)
        if not name.endswith(".csv") or not os.path.isfile(p):
            continue
        with open(p, "rb") as f:
            text = f.read().decode("utf-8")
        if text.startswith("\ufeff"):
            text = text[1:]
        first = text.split("\n", 1)[0]
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for r in rd:
            if header is None:
                header = [h.strip() for h in r]
                continue
            cells = [c.strip() for c in r]
            if not any(cells):
                continue
            row = {}
            for h, c in zip(header, cells):
                row[h] = c if c != "" else None
            rows.append(row)
    return rows


def parse_time(s, fmt, off):
    if fmt == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        sign = -1 if off[0] == "-" else 1
        hh, mm = off[1:].split(":")
        return (dt - sign * timedelta(hours=int(hh), minutes=int(mm))).replace(tzinfo=timezone.utc)
    s = s.replace("Z", "+00:00")
    return datetime.fromisoformat(s)


def parse_dur(s, fmt):
    if fmt == "clock":
        t = 0
        for p in s.split(":"):
            t = t * 60 + int(p)
        return t
    return int(s)


def median(v):
    v = sorted(v)
    n = len(v)
    if n % 2:
        return Fraction(v[n // 2])
    return Fraction(v[n // 2 - 1] + v[n // 2], 2)


def main():
    ind, outp = sys.argv[1], sys.argv[2]
    cb = json.load(open(os.path.join(ind, "codebook.json"), encoding="utf-8"))
    wt = json.load(open(os.path.join(ind, "weighting.json"), encoding="utf-8"))
    plan = json.load(open(os.path.join(ind, "tables.json"), encoding="utf-8"))
    vkeys = list(cb["versions"].keys())
    stats = {v: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0) for v in vkeys}

    recs = []
    for r in read_exports(ind):
        v = r["form_version"]
        m = cb["versions"][v]["meta"]
        rid = r.get(m["id"])
        complete = r.get(m["status"]) == m["complete"]
        sub = r.get(m["submitted"])
        t = parse_time(sub, m["submitted_format"], m.get("utc_offset")) if sub else datetime.min.replace(tzinfo=timezone.utc)
        du = r.get(m["duration"])
        dur = parse_dur(du, m["duration_format"]) if du else 0
        lp = r.get(m["last_page"])
        lp = int(lp) if lp else 0
        recs.append(dict(v=v, id=rid, complete=complete, t=t, dur=dur, lp=lp, row=r))
        stats[v]["rows"] += 1

    best = {}
    for rec in recs:
        k = rec["id"]
        key = (rec["complete"], rec["t"])
        if k not in best or key > best[k][0]:
            best[k] = (key, rec)
    kept = []
    for rec in recs:
        if best[rec["id"]][1] is rec:
            kept.append(rec)
        else:
            stats[rec["v"]]["duplicates"] += 1
    # exact-tie copies: the 'is' check keeps exactly one object
    k2 = []
    for rec in kept:
        if not rec["complete"] and rec["lp"] < cb["partial_min_page"]:
            stats[rec["v"]]["short_partials"] += 1
        else:
            k2.append(rec)
    med = {}
    for v in vkeys:
        d = [r["dur"] for r in k2 if r["v"] == v and r["complete"]]
        if d:
            med[v] = median(d)
    k3 = []
    for rec in k2:
        if rec["complete"] and rec["dur"] * 5 < med[rec["v"]] * 2:
            stats[rec["v"]]["speeders"] += 1
        else:
            k3.append(rec)
    for rec in k3:
        stats[rec["v"]]["complete" if rec["complete"] else "partial"] += 1

    questions = {q["id"]: q for q in cb["questions"]}
    refyear = int(cb["reference_date"][:4])

    def codes_of(q):
        items = q["bands"] if q["type"] == "age" else q["options"]
        return items

    def conv(e, val):
        rc = e.get("recode")
        if rc is not None:
            return rc[val]
        return int(val)

    def read(q, e, row):
        t = q["type"]
        if t == "single":
            val = row.get(e["column"])
            if val is None:
                return None
            code = conv(e, val)
            if any(o.get("missing") and o["code"] == code for o in q["options"]):
                return None
            return code
        if t == "age":
            val = row.get(e["column"])
            if val is None:
                return None
            src = e.get("source")
            if src == "band":
                return conv(e, val)
            age = int(val)
            if src == "birth_year":
                age = refyear - age
            for b in q["bands"]:
                if b["min"] <= age <= b["max"]:
                    return b["code"]
            return None
        chosen = set()
        if "columns" in e:
            for code, col in e["columns"].items():
                if row.get(col) == "1":
                    chosen.add(int(code))
        else:
            val = row.get(e["column"])
            if val is not None:
                for el in val.split(e["separator"]):
                    el = el.strip()
                    if el:
                        chosen.add(conv(e, el))
        opts = {o["code"]: o for o in q["options"]}
        exc = {c for c in chosen if opts[c].get("exclusive")}
        if exc and len(exc) < len(chosen):
            chosen -= exc
        elif len(exc) >= 2:
            chosen = set()
        chosen = {c for c in chosen if not opts[c].get("missing")}
        return frozenset(chosen) if chosen else None

    def has(ans, codes):
        if ans is None:
            return False
        if isinstance(ans, frozenset):
            return any(c in ans for c in codes)
        return ans in codes

    for rec in k3:
        ans = {}
        asked = {}
        for q in cb["questions"]:
            e = q["versions"].get(rec["v"])
            a = e is not None and (rec["complete"] or e["page"] <= rec["lp"])
            if a and q.get("ask_if"):
                ai = q["ask_if"]
                a = asked.get(ai["question"], False) and has(ans.get(ai["question"]), ai["codes"])
            asked[q["id"]] = a
            ans[q["id"]] = read(q, e, rec["row"]) if a else None
        rec["ans"] = ans

    n = len(k3)
    w = [1.0] * n
    if n:
        for _ in range(wt.get("max_iterations", 100)):
            maxdev = 0.0
            for dim in wt["dimensions"]:
                qid = dim["question"]
                present = {rec["ans"][qid] for rec in k3 if rec["ans"][qid] is not None}
                tg = {int(c): float(x) for c, x in dim["targets"].items() if int(c) in present}
                s = sum(tg.values())
                if not tg or s == 0:
                    continue
                cat = [rec["ans"][qid] if rec["ans"][qid] in tg else None for rec in k3]
                T = sum(w[i] for i in range(n) if cat[i] is not None)
                W = {}
                for i in range(n):
                    if cat[i] is not None:
                        W[cat[i]] = W.get(cat[i], 0.0) + w[i]
                f = {c: tg[c] / s * T / W[c] for c in W}
                for c in f:
                    maxdev = max(maxdev, abs(f[c] - 1))
                for i in range(n):
                    if cat[i] is not None:
                        w[i] *= f[cat[i]]
            if maxdev <= wt.get("tolerance", 1e-10):
                break
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        m = sum(w) / n
        w = [x / m for x in w]

    def r2(x):
        return None if x is None else round(x + 0.0, 2)

    summary = {"versions": [dict(version=v, **stats[v]) for v in vkeys], "respondents": n}
    if n:
        summary.update(effective_n=r2(sum(w) ** 2 / sum(x * x for x in w)), weight_min=r2(min(w)), weight_max=r2(max(w)))
    else:
        summary.update(effective_n=None, weight_min=None, weight_max=None)

    cols = [("total", None, None)]
    for bq in plan["banner"]:
        for o in codes_of(questions[bq]):
            if not o.get("missing"):
                cols.append((f"{bq}:{o['code']}", bq, o["code"]))
    tables = []
    for t in plan["tables"]:
        q = questions[t["question"]]
        opts = [o for o in codes_of(q) if not o.get("missing")]
        nets = t.get("nets", [])
        out = []
        for cid, bq, bc in cols:
            idx = [i for i, rec in enumerate(k3)
                   if rec["ans"][q["id"]] is not None and (bq is None or rec["ans"][bq] == bc)]
            wb = sum(w[i] for i in idx)
            vals = {}
            keys = [str(o["code"]) for o in opts] + [x["id"] for x in nets] + (["mean"] if t.get("mean") else [])
            if not idx:
                vals = {k: None for k in keys}
                out.append(dict(column=cid, base=0, weighted_base=0, values=vals))
                continue
            for o in opts:
                vals[str(o["code"])] = r2(100 * sum(w[i] for i in idx if has(k3[i]["ans"][q["id"]], [o["code"]])) / wb) if wb else None
            for x in nets:
                vals[x["id"]] = r2(100 * sum(w[i] for i in idx if has(k3[i]["ans"][q["id"]], x["codes"])) / wb) if wb else None
            if t.get("mean"):
                sc = {o["code"]: o["score"] for o in opts}
                vals["mean"] = r2(sum(w[i] * sc[k3[i]["ans"][q["id"]]] for i in idx) / wb) if wb else None
            out.append(dict(column=cid, base=len(idx), weighted_base=r2(wb), values=vals))
        tables.append(dict(table=t["id"], columns=out))

    with open(outp, "w", encoding="utf-8") as f:
        json.dump(dict(survey=cb["survey"], summary=summary, tables=tables), f, indent=1)


main()
